                Text(
                  title,
                  style: TextStyle(
                      color: GlassTheme.textColor(context),
                      fontSize: 15,
                      fontWeight: FontWeight.w700),
                ),
                CommonUtil.vGap2,
                Text(
                  subtitle,
                  style: TextStyle(
                      color: GlassTheme.secondaryTextColor(context),
                      fontSize: 11,
                      fontWeight: FontWeight.w500),
                ),
              ],
            ),
          ),
          Transform.scale(
            scale: 0.8,
            child: Switch.adaptive(
              value: value,
              onChanged: onChanged,
              activeTrackColor: GlassTheme.textColor(context).withValues(alpha: 0.3),
              activeThumbColor: GlassTheme.textColor(context),
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildActionTile(
      BuildContext context, IconData icon, String title, String subtitle,
      {required VoidCallback onTap, Widget? trailing}) {
    return InkWell(
      onTap: onTap,
      child: Padding(
        padding: CommonUtil.pHor16V12,
        child: Row(
          children: [
            Container(
              padding: CommonUtil.pAll8,
              decoration: BoxDecoration(
                color: GlassTheme.textColor(context).withValues(alpha: 0.08),
                borderRadius: CommonUtil.bRadius10,
              ),
              child: Icon(icon, color: GlassTheme.textColor(context), size: 18),
            ),
            CommonUtil.hGap14,
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    title,
                    style: TextStyle(
                        color: GlassTheme.textColor(context),
                        fontSize: 15,
                        fontWeight: FontWeight.w700),
                  ),
                  CommonUtil.vGap1,
                  Text(
                    subtitle,
                    style: TextStyle(
                        color: GlassTheme.secondaryTextColor(context),
                        fontSize: 11,
                        fontWeight: FontWeight.w500),
                  ),
                ],
              ),
            ),
            trailing ??
                Icon(Icons.arrow_forward_ios_rounded,
                    color:
                        GlassTheme.secondaryTextColor(context).withValues(alpha: 0.3),
                    size: 12),
          ],
        ),
      ),
    );
  }

  Widget _buildDivider(BuildContext context) {
    return Divider(
        height: 1,
        color: GlassTheme.glassBorder(context),
        indent: 16,
        endIndent: 16);
  }

  Widget _buildDangerousSection(BuildContext context) {
    return Column(
      children: [
        _buildGlassGroup(
          context,
          [
            _buildActionTile(
              context,
              Icons.delete_forever_rounded,
              'Delete Account',
              'Permanently remove all your Zinko data',
              onTap: () => _showDeleteConfirmation(context),
            ),
          ],
        ),
        CommonUtil.vGap16,
        Text(
          'Please note that account deletion is irreversible. You will lose all your booking history and wallet balance.',
          textAlign: TextAlign.center,
          style: TextStyle(
              color: GlassTheme.tertiaryTextColor(context),
              fontSize: 11,
              fontWeight: FontWeight.w500),
        ).animate(delay: 500.ms).fadeIn(),
      ],
    );
  }

  void _showDeleteConfirmation(BuildContext context) {
    ZinkoCommonDialog.show(
      context: context,
      title: 'DELETE ACCOUNT?',
      message: 'Are you sure you want to delete your account? This action cannot be undone and all your data will be permanently removed.',
      icon: Icons.delete_forever_rounded,
      iconColor: AppColors.error,
      actionLabel: 'DELETE',
      actionColor: AppColors.error,
      onAction: () {
        final userState = context.read<UserBloc>().state;
        if (userState is UserLoaded) {
          context.read<UserBloc>().add(DeleteUserEvent(userState.user.userCode));
        }
        Navigator.pop(context);
      },
    );
  }
}

